# Generated by Descant: acceptance tests.

# frozen_string_literal: true

require "rails_helper"

RSpec.describe Invoices::ReservationRequest do
  # The request is the only value that carries the company across the
  # reservation port, so a request with no company must not be built.
  it "refuses to build a reservation request without a company or with an unknown disposition" do
    attributes = {
      company_id: 1, invoice_id: 10, operation_id: SecureRandom.uuid, generation: 1,
      disposition: "active", entries: [3, 1]
    }

    expect { described_class.new(**attributes, company_id: nil) }.to raise_error(ArgumentError)
    expect { described_class.new(**attributes, disposition: "deleted") }.to raise_error(ArgumentError)
    expect(described_class.new(**attributes).company_id).to eq(1)
  end

  # "The intent must store the whole request, so retries and recovery resend the stored bytes and never recompute."
  # A caller that changes its own array after building the request must not
  # change the entries the request sends.
  it "keeps the request fields, stores canonical frozen entries and ignores later changes to the caller's array" do
    operation_id = SecureRandom.uuid
    entries = [3, 1, 3]

    request = described_class.new(company_id: 7, invoice_id: 11, operation_id:, generation: 2,
                                  disposition: "retained", entries:)
    entries << 99
    entries.delete(1)

    expect([request.company_id, request.invoice_id, request.operation_id, request.generation, request.disposition])
      .to eq([7, 11, operation_id, 2, "retained"])
    expect(request.entries).to eq([1, 3])
    expect(request.entries).to be_frozen
    expect(entries).not_to be_frozen
    expect(request).to eq(described_class.new(company_id: 7, invoice_id: 11, operation_id:, generation: 2,
                                              disposition: "retained", entries: [1, 3]))
  end
end
